int dbMemoSize = pega_rules_utilities.pxGetColumnSize("Link-Attachment","pyMemo");
if(LinkMemo.length() > dbMemoSize ){
  LinkMemo = LinkMemo.substring(0, dbMemoSize);
}

boolean boo = tools.getPrimaryPage().containsKey("pyAttachments");
try {
	if (boo==true) 
		tools.getPrimaryPage().getIfPresent(".pyAttachments").removeFromClipboard();
	ParameterPage parampage = new ParameterPage();
	parampage.putString("LinkRefFrom",tools.getPrimaryPage().getString("pzInsKey"));
    tools.removeDataPage("D_AttachmentList", parampage);


}catch(Exception e){
	oLog.error(e);
}

// First get pyCorrPage handle
String corrHandle = "";
try {
corrHandle = tools.getDatabase().getHandle(myStepPage);
}
catch (DatabaseException e)
{
return false;
}

ClipboardProperty cp_CorrSummary = tools.getPrimaryPage().getProperty(".pxCorrSummary(" + corrHandle + ")");
ClipboardPage pg_CorrSummary = cp_CorrSummary.getPageValue();
pg_CorrSummary.putString(".pxCorrType", myStepPage.getString(".pyCorrStreamType"));
pg_CorrSummary.putString(".pxCorrName", myStepPage.getString(".pyCorrStreamName"));
pg_CorrSummary.putString(".pxRecipientPartyUri", tools.getPrimaryPage().getString(".pyWorkParty(" + myStepPage.getString(".pyCorrPartyRole") + ").pyWorkPartyUri"));
